  VALUES ('L1 PMB 8.1 (fixtures)', v_lib, 'mapeada', 'own_catalog', true) RETURNING id INTO v_spmb;

  -- Notices déjà au catalogue, et ce que leurs imports passés ont laissé (book_external_ids).
  INSERT INTO public.books (titulo, bib_ref, tipo_material, owner_library_id) VALUES ('L1 Notice connue', 'L1-K1', 'livro', v_lib) RETURNING id INTO v_k1;
  INSERT INTO public.books (titulo, bib_ref, tipo_material, owner_library_id) VALUES ('L1 Notice connue sans ISBN', 'L1-K2', 'livro', v_lib) RETURNING id INTO v_k2;
  INSERT INTO public.books (titulo, bib_ref, tipo_material, owner_library_id, isbn) VALUES ('L1 Une autre notice au meme ISBN', 'L1-Z', 'livro', v_lib, '978-3-16-148410-0') RETURNING id INTO v_z;
  INSERT INTO public.books (titulo, bib_ref, tipo_material, owner_library_id) VALUES ('L1 Notice reattribuee a B', 'L1-K3', 'livro', v_lib) RETURNING id INTO v_k3;
  INSERT INTO public.books (titulo, bib_ref, tipo_material, owner_library_id) VALUES ('L1 Notice sans fonds', 'L1-K4', 'livro', v_lib) RETURNING id INTO v_k4;
  INSERT INTO public.books (titulo, bib_ref, tipo_material, owner_library_id) VALUES ('L1 Notice a cle repetee', 'L1-K5', 'livro', v_lib) RETURNING id INTO v_k5;
  INSERT INTO public.books (titulo, bib_ref, tipo_material, owner_library_id) VALUES ('L1 Notice entierement detenue', 'L1-K6', 'livro', v_lib) RETURNING id INTO v_k6;
  INSERT INTO public.books (titulo, bib_ref, tipo_material, owner_library_id) VALUES ('L1 Ambigue une', 'L1-A1', 'livro', v_lib) RETURNING id INTO v_a1;
  INSERT INTO public.books (titulo, bib_ref, tipo_material, owner_library_id) VALUES ('L1 Ambigue deux', 'L1-A2', 'livro', v_lib) RETURNING id INTO v_a2;
  INSERT INTO public.books (titulo, bib_ref, tipo_material, owner_library_id) VALUES ('L1 Notice de B', 'L1-KB', 'livro', v_libB) RETURNING id INTO v_kb;
  INSERT INTO public.books (titulo, bib_ref, tipo_material, owner_library_id) VALUES ('L1 Notice du depot', 'L1-KD', 'livro', v_lib) RETURNING id INTO v_kd;
  INSERT INTO public.books (titulo, bib_ref, tipo_material, owner_library_id) VALUES ('L1 Notice de la deposante', 'L1-KD2', 'livro', v_libB) RETURNING id INTO v_kd2;
  INSERT INTO public.books (titulo, bib_ref, tipo_material, owner_library_id) VALUES ('L1 Notice a reattribuer', 'L1-R', 'livro', v_lib) RETURNING id INTO v_rb;
  INSERT INTO public.book_holdings (book_id, library_id)
  VALUES (v_k1, v_lib), (v_k2, v_lib), (v_z, v_lib), (v_k3, v_libB), (v_k5, v_lib), (v_k6, v_lib),
         (v_a1, v_lib), (v_a2, v_lib), (v_kb, v_libB), (v_kd, v_lib), (v_kd2, v_libB), (v_rb, v_lib), (v_rb, v_libB);
  -- Exemplaires déjà là (codes d'origine) : K1 en a un, K6 a tous ceux de sa ligne.
  INSERT INTO public.exemplares (bib_ref, tombo, library_id, holding_id, source_item_code, circulation_policy, visibility)
  SELECT 'L1-K1', 'L1-EXIST-1', v_lib, h.id, 'L1-EX-1', 'consulta', 'public' FROM public.book_holdings h WHERE h.book_id = v_k1 AND h.library_id = v_lib;
  INSERT INTO public.exemplares (bib_ref, tombo, library_id, holding_id, source_item_code, circulation_policy, visibility)
  SELECT 'L1-K6', 'L1-EXIST-6', v_lib, h.id, 'L1-EX-6', 'consulta', 'public' FROM public.book_holdings h WHERE h.book_id = v_k6 AND h.library_id = v_lib;
  PERFORM ingest.fn_record_book_external_id(v_k1, v_lib, v_s1, 'L1-K1');
  PERFORM ingest.fn_record_book_external_id(v_k2, v_lib, v_s1, 'L1-K2');
  PERFORM ingest.fn_record_book_external_id(v_k3, v_lib, v_s1, 'L1-K3');
  PERFORM ingest.fn_record_book_external_id(v_k4, v_lib, v_s1, 'L1-K4');
  PERFORM ingest.fn_record_book_external_id(v_k5, v_lib, v_s1, 'L1-K5');
  PERFORM ingest.fn_record_book_external_id(v_k6, v_lib, v_s1, 'L1-K6');
  PERFORM ingest.fn_record_book_external_id(v_a1, v_lib, v_s1, 'L1-AMB');   -- même valeur, deux sources,
  PERFORM ingest.fn_record_book_external_id(v_a2, v_lib, v_s2, 'L1-AMB');   -- deux notices
  PERFORM ingest.fn_record_book_external_id(v_kb, v_libB, v_sB, 'L1-B1');  -- connue chez B seulement
  PERFORM ingest.fn_record_book_external_id(v_kd, v_lib, v_s1, 'L1-DEP1');
  PERFORM ingest.fn_record_book_external_id(v_kd2, v_libB, v_sB, 'L1-DEP2');

  -- Le nouvel export (source 2 de BLMF), lu par l'edge function : lignes non rapprochées.
  INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
  VALUES (v_s2, v_lib, 'essai/l1-nouvel-export.marc', 'l1-nouvel-export.marc', 'marc_iso2709', 'parsed') RETURNING id INTO v_run2;
  INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, isbn, match_status, editorial_decision, normalized_payload)
  VALUES (v_run2, 1,  'L1-K1',   'L1 Notice connue (nouvel export)', NULL, 'unreviewed', 'pending',
          '{"items": [{"source_item_code": "L1-EX-1", "call_number": "K1 A"}, {"source_item_code": "L1-EX-2", "call_number": "K1 B"}]}'::jsonb),
         (v_run2, 2,  'L1-B1',   'L1 Homonyme de la notice de B', NULL, 'unreviewed', 'pending', '{"items": []}'::jsonb),
         (v_run2, 3,  'L1-K2',   'L1 Connue, et un ISBN pris ailleurs', '978-3-16-148410-0', 'unreviewed', 'pending', '{"items": []}'::jsonb),
         (v_run2, 4,  'L1-ISBN', 'L1 Temoin du meme ISBN', '978-3-16-148410-0', 'unreviewed', 'pending', '{"items": []}'::jsonb),
         (v_run2, 5,  'L1-K5',   'L1 Cle repetee, premiere', NULL, 'unreviewed', 'pending', '{"items": []}'::jsonb),
         (v_run2, 6,  ' L1-K5 ', 'L1 Cle repetee, seconde', NULL, 'unreviewed', 'pending', '{"items": []}'::jsonb),
         (v_run2, 7,  'L1-AMB',  'L1 Valeur ambigue', NULL, 'unreviewed', 'pending', '{"items": []}'::jsonb),
         (v_run2, 8,  'L1-K3',   'L1 Reconnue, reattribuee', NULL, 'unreviewed', 'pending',
          '{"items": [{"source_item_code": "L1-EX-3", "call_number": "K3"}]}'::jsonb),
         (v_run2, 9,  'L1-K4',   'L1 Reconnue, fonds supprime', NULL, 'unreviewed', 'pending', '{"items": []}'::jsonb),
         (v_run2, 10, 'L1-NEUF', 'L1 Vraiment nouvelle', NULL, 'unreviewed', 'pending', '{"items": []}'::jsonb),
         (v_run2, 11, 'L1-K6',   'L1 Reconnue, tout deja la', NULL, 'unreviewed', 'pending',
          '{"items": [{"source_item_code": "L1-EX-6", "call_number": "K6"}]}'::jsonb);
  SELECT id INTO v_r1 FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2 AND row_no = 1;
  SELECT id INTO v_r2 FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2 AND row_no = 2;
  SELECT id INTO v_r3 FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2 AND row_no = 3;
  SELECT id INTO v_r4 FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2 AND row_no = 4;
  SELECT id INTO v_r5 FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2 AND row_no = 5;
  SELECT id INTO v_r6 FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2 AND row_no = 6;
  SELECT id INTO v_r7 FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2 AND row_no = 7;
  SELECT id INTO v_r8 FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2 AND row_no = 8;
  SELECT id INTO v_r9 FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2 AND row_no = 9;
  SELECT id INTO v_r10 FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2 AND row_no = 10;
  SELECT id INTO v_r11 FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2 AND row_no = 11;
  -- Le rapprochement du run, comme l'edge function le lance après la lecture.
  v_res := ingest.fn_match_partner_catalog_run(v_run2);

  -- ── T1 ──────────────────────────────────────────────────────────────
  v_t := 'T1 reconnue par une autre source de la meme bibliotheque ; la meme valeur chez une autre bibliotheque : pas reconnue';
  BEGIN
    v_res := ingest.fn_match_partner_catalog_row(v_r1);   -- rejoué : même verdict
    IF (SELECT sr.match_status = 'known_record' AND sr.proposed_book_id = v_k1 AND sr.proposed_book_draft_id IS NULL
          FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = v_r1)
       AND (SELECT count(*) FROM ingest.partner_catalog_match_candidates mc WHERE mc.staging_row_id = v_r1) = 1
       AND (SELECT mc.match_method = 'external_id' AND mc.match_score = 100 AND mc.candidate_type = 'book' AND mc.candidate_id = v_k1
                   AND mc.details->>'external_id' = 'L1-K1'
              FROM ingest.partner_catalog_match_candidates mc WHERE mc.staging_row_id = v_r1)
       AND v_res->>'top_match_method' = 'external_id' AND v_res->>'match_status' = 'known_record'
       AND (v_res->>'top_candidate_id')::bigint = v_k1 AND (v_res->>'top_match_score')::numeric = 100
       AND (SELECT sr.confidence FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = v_r1) = 100
       AND (SELECT sr.match_status = 'new_record' AND sr.proposed_book_id IS NULL
              FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = v_r2)
       AND NOT EXISTS (SELECT 1 FROM ingest.partner_catalog_match_candidates mc WHERE mc.staging_row_id = v_r2)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_res::text,'NULL')||' ; homonyme B='
         ||coalesce((SELECT sr.match_status||'/'||coalesce(sr.proposed_book_id::text,'-') FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = v_r2),'NULL')); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T2 ──────────────────────────────────────────────────────────────
  v_t := 'T2 court-circuit : reconnue vers SA notice, sans candidat ISBN ; le temoin du meme ISBN est matched_book vers l''autre';
  BEGIN
    IF (SELECT sr.match_status = 'known_record' AND sr.proposed_book_id = v_k2 FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = v_r3)
       AND (SELECT count(*) FROM ingest.partner_catalog_match_candidates mc WHERE mc.staging_row_id = v_r3) = 1
       AND NOT EXISTS (SELECT 1 FROM ingest.partner_catalog_match_candidates mc WHERE mc.staging_row_id = v_r3 AND mc.match_method <> 'external_id')
       AND (SELECT sr.match_status = 'matched_book' AND sr.proposed_book_id = v_z FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = v_r4)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '
         ||(SELECT string_agg(sr.row_no||'='||sr.match_status||'/'||coalesce(sr.proposed_book_id::text,'-'), ' ' ORDER BY sr.row_no)
              FROM ingest.partner_catalog_staging_rows sr WHERE sr.id IN (v_r3, v_r4))
         ||' candidats='||(SELECT string_agg(mc.match_method||':'||mc.candidate_id, ',') FROM ingest.partner_catalog_match_candidates mc WHERE mc.staging_row_id = v_r3)); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T3 ──────────────────────────────────────────────────────────────
  v_t := 'T3 une cle que portent deux lignes du fichier (connue) : aucune n''est reconnue';
  BEGIN
    IF (SELECT count(*) FROM ingest.partner_catalog_staging_rows sr
         WHERE sr.id IN (v_r5, v_r6) AND sr.match_status <> 'known_record' AND sr.proposed_book_id IS DISTINCT FROM v_k5) = 2
       AND NOT EXISTS (SELECT 1 FROM ingest.partner_catalog_match_candidates mc
                        WHERE mc.staging_row_id IN (v_r5, v_r6) AND mc.match_method = 'external_id')
       AND ingest.fn_h20_cle_de_la_ligne(v_r5) IS NULL
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '
         ||(SELECT string_agg(sr.row_no||'='||sr.match_status||'/'||coalesce(sr.proposed_book_id::text,'-'), ' ' ORDER BY sr.row_no)
              FROM ingest.partner_catalog_staging_rows sr WHERE sr.id IN (v_r5, v_r6))); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T4 ──────────────────────────────────────────────────────────────
  v_t := 'T4 valeur ambigue (deux notices) : pas reconnue, un avertissement non repete ; ambiguite levee : reconnue, avertissement parti';
  BEGIN
    v_res := ingest.fn_match_partner_catalog_row(v_r7);   -- rejoué : toujours UN avertissement
    SELECT sr.match_status, (SELECT count(*) FROM jsonb_array_elements(sr.warnings) w WHERE w->>'kind' = 'known_record_ambiguous'),
           (SELECT w->'book_ids' FROM jsonb_array_elements(sr.warnings) w WHERE w->>'kind' = 'known_record_ambiguous' LIMIT 1)::text
      INTO v_txt, v_n, v_hint
      FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = v_r7;
    -- l'ambiguïté levée (la seconde notice n'a plus l'identifiant), la ligne rejouée
    DELETE FROM public.book_external_ids WHERE book_id = v_a2 AND value = 'L1-AMB';
    v_res2 := ingest.fn_match_partner_catalog_row(v_r7);
    IF v_txt <> 'known_record' AND v_n = 1
       AND v_hint = to_jsonb(ARRAY[least(v_a1, v_a2), greatest(v_a1, v_a2)])::text
       AND v_res->>'top_match_method' IS DISTINCT FROM 'external_id'
       AND v_res2->>'match_status' = 'known_record' AND (v_res2->>'top_candidate_id')::bigint = v_a1
       AND NOT EXISTS (SELECT 1 FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.warnings) w
                        WHERE sr.id = v_r7 AND w->>'kind' = 'known_record_ambiguous')
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : statut='||coalesce(v_txt,'NULL')||' avertissements='||coalesce(v_n::text,'NULL')
         ||' notices='||coalesce(v_hint,'NULL')||' apres='||coalesce(v_res2::text,'NULL')); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T5 ──────────────────────────────────────────────────────────────
  v_t := 'T5 depot compagnon : reconnue par la bibliotheque de DESTINATION, pas par la deposante (bibliotheque du run)';
  BEGIN
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_sdep, v_libB, 'essai/l1-depot.marc', 'l1-depot.marc', 'marc_iso2709', 'parsed') RETURNING id INTO v_rdep;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, match_status, editorial_decision, normalized_payload)
    VALUES (v_rdep, 1, 'L1-DEP1', 'L1 Depot : connue a la destination', 'unreviewed', 'pending', '{"items": []}'::jsonb),
           (v_rdep, 2, 'L1-DEP2', 'L1 Depot : connue chez la deposante', 'unreviewed', 'pending', '{"items": []}'::jsonb);
    PERFORM ingest.fn_match_partner_catalog_run(v_rdep);
    IF (SELECT sr.match_status = 'known_record' AND sr.proposed_book_id = v_kd FROM ingest.partner_catalog_staging_rows sr
         WHERE sr.run_id = v_rdep AND sr.row_no = 1)
       AND (SELECT sr.match_status = 'new_record' AND sr.proposed_book_id IS NULL FROM ingest.partner_catalog_staging_rows sr
             WHERE sr.run_id = v_rdep AND sr.row_no = 2)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '
         ||(SELECT string_agg(sr.row_no||'='||sr.match_status||'/'||coalesce(sr.proposed_book_id::text,'-'), ' ' ORDER BY sr.row_no)
              FROM ingest.partner_catalog_staging_rows sr WHERE sr.run_id = v_rdep)); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T6 ──────────────────────────────────────────────────────────────
  v_t := 'T6 proposed_book_held (ecran, jeton de la coordination) : vrai, faux (reattribuee, sans fonds), NULL sans notice proposee';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    SELECT string_agg(l.row_no || '=' || l.match_status || '/' || coalesce(l.proposed_book_held::text, 'null'), ' ' ORDER BY l.row_no)
      INTO v_txt
      FROM public.fn_import_list_run_rows(v_run2) l
     WHERE l.id IN (v_r1, v_r8, v_r9, v_r10);
    EXECUTE 'RESET ROLE';
    IF v_txt = '1=known_record/true 8=known_record/false 9=known_record/false 10=new_record/null'
       AND (SELECT (p.proargnames)[array_length(p.proargnames, 1)] FROM pg_proc p
             WHERE p.oid = 'public.fn_import_list_run_rows(bigint)'::regprocedure) = 'proposed_book_held'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_txt,'NULL')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T7 ──────────────────────────────────────────────────────────────
  v_t := 'T7 « Creer » refuse sur une ligne reconnue ; posee de force, aucune notice ; « Rejeter » passe';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_hint := NULL;
    BEGIN
      PERFORM public.fn_import_set_editorial(v_run2, ARRAY[v_r1], 'accept_new', NULL);
      v_hint := 'accepte';
    EXCEPTION WHEN OTHERS THEN v_hint := SQLERRM;
    END;
    -- Posée de force (postgres : le schéma ingest est fermé à l'API), la promotion l'ignore.
    UPDATE ingest.partner_catalog_staging_rows SET editorial_decision = 'accept_new' WHERE id = v_r1;
    v_hint2 := NULL;
    BEGIN
      v_res := public.fn_import_promote(v_run2, ARRAY['known_record', 'new_record'], ARRAY['accept_new'], p_row_ids := ARRAY[v_r1]);
      v_hint2 := 'appel sans erreur';
    EXCEPTION WHEN OTHERS THEN v_hint2 := 'refuse';
    END;
    v_ok := (SELECT sr.created_book_draft_id IS NULL FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = v_r1)
            AND NOT EXISTS (SELECT 1 FROM ingest.partner_catalog_row_to_draft m WHERE m.staging_row_id = v_r1)
            AND NOT EXISTS (SELECT 1 FROM public.book_drafts d WHERE d.titulo = 'L1 Notice connue (nouvel export)');
    UPDATE ingest.partner_catalog_staging_rows SET editorial_decision = 'pending' WHERE id = v_r1;
    v_res := public.fn_import_set_editorial(v_run2, ARRAY[v_r9], 'reject', 'L1 : rejet d''une ligne reconnue');
    IF v_hint LIKE '%incompatible%' AND v_ok
       AND (v_res->>'updated_rows')::int = 1
       AND (SELECT editorial_decision FROM ingest.partner_catalog_staging_rows WHERE id = v_r9) = 'reject'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : creer='||coalesce(v_hint,'NULL')||' promotion='||coalesce(v_hint2,'NULL')
         ||' sans notice='||coalesce(v_ok::text,'NULL')||' rejet='||coalesce(v_res::text,'NULL')); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T8 ──────────────────────────────────────────────────────────────
  v_t := 'T8 « Rapprocher » des lignes reconnues : exemplaires sur la notice reconnue, code deja la non recree, ligne detenue rejetee ; publies apres revision';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_res := public.fn_import_reconcile_duplicates(v_run2, ARRAY[v_r1, v_r8, v_r11]);
    v_lot := (v_res->>'batch_id')::bigint;
    v_res2 := public.fn_batch_review_request(v_lot, 'L1 : rapprochement de lignes reconnues');
    EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    PERFORM public.fn_batch_review_verdict((v_res2->>'review_id')::bigint, 'approved', NULL);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_res2 := public.publish_catalog_batch(v_lot);
    IF (v_res->>'created_items')::int = 2 AND (v_res->>'items_skipped_code_taken')::int = 2
       AND (v_res->>'rows_already_held')::int = 1 AND coalesce((v_res->>'skipped_rows')::int, 0) = 0
       AND (SELECT count(*) FROM ingest.partner_catalog_staging_rows sr
             WHERE sr.id IN (v_r1, v_r8) AND sr.editorial_decision = 'accept_duplicate' AND sr.created_exemplar_draft_id IS NOT NULL
               AND sr.created_book_draft_id IS NULL AND sr.match_status = 'known_record') = 2
       AND (SELECT editorial_decision FROM ingest.partner_catalog_staging_rows WHERE id = v_r11) = 'reject'
       AND NOT EXISTS (SELECT 1 FROM public.book_drafts d JOIN ingest.partner_catalog_row_to_draft m ON m.draft_id = d.id
                        WHERE m.staging_row_id IN (v_r1, v_r8, v_r11))
       -- publiés sur les notices reconnues ; L1-EX-1 et L1-EX-6 n'existent qu'une fois
       AND (SELECT count(*) FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id
             WHERE e.source_item_code = 'L1-EX-2' AND e.library_id = v_lib AND h.book_id = v_k1) = 1
       AND (SELECT count(*) FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id
             WHERE e.source_item_code = 'L1-EX-3' AND e.library_id = v_lib AND h.book_id = v_k3 AND h.library_id = v_lib) = 1
       AND (SELECT count(*) FROM public.exemplares e WHERE e.source_item_code IN ('L1-EX-1', 'L1-EX-6')) = 2
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : rapprocher='||coalesce(v_res::text,'NULL')||' publier='||coalesce(v_res2::text,'NULL')
         ||' lignes='||(SELECT string_agg(sr.row_no||'='||sr.match_status||'/'||coalesce(sr.editorial_decision,'-')||'/'||coalesce(sr.created_exemplar_draft_id::text,'-'), ' ' ORDER BY sr.row_no)
                          FROM ingest.partner_catalog_staging_rows sr WHERE sr.id IN (v_r1, v_r8, v_r11))); END IF;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_hint,'')||' '||SQLERRM); END;

  -- ── T9 ──────────────────────────────────────────────────────────────
  v_t := 'T9 la fixture PMB reimportee a l''identique (second run, meme source) : 64 known_record, 0 new_record, 0 possible_duplicate';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    -- Premier import, comme aller_retour_pmb_tests.sql : promu, révisé, publié.
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_spmb, v_lib, 'essai/pmb.iso', 'pmb.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_rpmb1;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, item_type, title, subtitle, responsibility_statement, authors, publisher, place_of_publication, publication_year, edition_statement, language, isbn, issn, subjects, raw_payload, normalized_payload, match_status, editorial_decision)
    SELECT v_rpmb1, r.row_no, r.external_key, r.item_type, r.title, r.subtitle, r.responsibility_statement, r.authors, r.publisher, r.place_of_publication, r.publication_year, r.edition_statement, r.language, r.isbn, r.issn, r.subjects, r.raw_payload, r.normalized_payload, 'new_record', 'accept_new'
      FROM jsonb_to_recordset(v_pmb)
      AS r(row_no integer, external_key text, item_type text, title text, subtitle text, responsibility_statement text, authors jsonb, publisher text, place_of_publication text, publication_year text, edition_statement text, language text, isbn text, issn text, subjects jsonb, raw_payload jsonb, normalized_payload jsonb);
    v_res := public.fn_import_promote(v_rpmb1, ARRAY['new_record'], ARRAY['accept_new']);
    v_lotp := (v_res->>'batch_id')::bigint;
    UPDATE public.book_drafts SET bib_ref = 'L1-PMB-REF-' || id WHERE batch_id = v_lotp AND bib_ref IS NULL;
    v_res := public.fn_batch_review_request(v_lotp);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    PERFORM public.fn_batch_review_verdict((v_res->>'review_id')::bigint, 'approved', NULL);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    PERFORM public.publish_catalog_batch(v_lotp);
    IF (SELECT count(*) FROM public.book_drafts WHERE batch_id = v_lotp AND status = 'published') <> 64 THEN
      RAISE EXCEPTION 'decor : % notice(s) publiee(s) sur 64', (SELECT count(*) FROM public.book_drafts WHERE batch_id = v_lotp AND status = 'published');
    END IF;
    -- Le réimport : les mêmes lignes, telles que l'edge function les écrit, non rapprochées.
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_spmb, v_lib, 'essai/pmb-reimport.iso', 'pmb-reimport.iso', 'marc_iso2709', 'parsed') RETURNING id INTO v_rpmb2;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, item_type, title, subtitle, responsibility_statement, authors, publisher, place_of_publication, publication_year, edition_statement, language, isbn, issn, subjects, raw_payload, normalized_payload, match_status, editorial_decision)
    SELECT v_rpmb2, r.row_no, r.external_key, r.item_type, r.title, r.subtitle, r.responsibility_statement, r.authors, r.publisher, r.place_of_publication, r.publication_year, r.edition_statement, r.language, r.isbn, r.issn, r.subjects, r.raw_payload, r.normalized_payload, 'unreviewed', 'pending'
      FROM jsonb_to_recordset(v_pmb)
      AS r(row_no integer, external_key text, item_type text, title text, subtitle text, responsibility_statement text, authors jsonb, publisher text, place_of_publication text, publication_year text, edition_statement text, language text, isbn text, issn text, subjects jsonb, raw_payload jsonb, normalized_payload jsonb);
    PERFORM ingest.fn_match_partner_catalog_run(v_rpmb2);
    -- Clés non uniques dans le fichier (le juge rend NULL) : aucune attendue.
    SELECT count(*) INTO v_k FROM ingest.partner_catalog_staging_rows sr
     WHERE sr.run_id = v_rpmb2 AND ingest.fn_h20_cle_de_la_ligne(sr.id) IS NULL;
    SELECT count(*) FILTER (WHERE sr.match_status = 'known_record'),
           count(*) FILTER (WHERE sr.match_status = 'known_record'
                              AND sr.proposed_book_id = (SELECT d.published_book_id
                                                           FROM ingest.partner_catalog_staging_rows s1
                                                           JOIN ingest.partner_catalog_row_to_draft m ON m.staging_row_id = s1.id
                                                           JOIN public.book_drafts d ON d.id = m.draft_id
                                                          WHERE s1.run_id = v_rpmb1 AND s1.external_key = sr.external_key))
      INTO v_n, v_m
      FROM ingest.partner_catalog_staging_rows sr WHERE sr.run_id = v_rpmb2;
    IF v_k = 0 AND v_n = 64 AND v_m = 64
       AND (SELECT count(*) FROM ingest.partner_catalog_staging_rows WHERE run_id = v_rpmb2) = 64
       AND NOT EXISTS (SELECT 1 FROM ingest.partner_catalog_staging_rows
                        WHERE run_id = v_rpmb2 AND match_status IN ('new_record', 'possible_duplicate', 'matched_book', 'matched_draft', 'manual_decision'))
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : cles non uniques='||coalesce(v_k::text,'NULL')||' known_record='||coalesce(v_n::text,'NULL')
         ||' sur la bonne notice='||coalesce(v_m::text,'NULL')||' ; '
         ||coalesce((SELECT string_agg(match_status||'='||c, ', ') FROM (SELECT match_status, count(*) c FROM ingest.partner_catalog_staging_rows
                                                                         WHERE run_id = v_rpmb2 GROUP BY 1) x), 'aucune ligne')
         ||' ; non reconnues : '||coalesce((SELECT string_agg(external_key||'/'||match_status, ' ' ORDER BY row_no) FROM ingest.partner_catalog_staging_rows
                                            WHERE run_id = v_rpmb2 AND match_status <> 'known_record'), '-')); END IF;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_hint,'')||' '||SQLERRM); END;

  -- ── T10 ─────────────────────────────────────────────────────────────
  v_t := 'T10 (IMP-28 c) rapproche publie a BLMF puis reattribue a B : l''identifiant reste a BLMF, aucun pour B';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_s1, v_lib, 'essai/l1-reattribution.marc', 'l1-reattribution.marc', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_rrat;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, match_status, editorial_decision, proposed_book_id, normalized_payload)
    VALUES (v_rrat, 1, 'L1-RAT', 'L1 Notice a reattribuer (exemplaire)', 'matched_book', 'pending', v_rb,
            '{"items": [{"source_item_code": "L1-RAT-X", "call_number": "R X"}]}'::jsonb)
    RETURNING id INTO v_rrow;
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_res := public.fn_import_reconcile_duplicates(v_rrat, ARRAY[v_rrow]);
    v_lotr := (v_res->>'batch_id')::bigint;
    v_res := public.fn_batch_review_request(v_lotr);
    EXECUTE 'RESET ROLE';
    SELECT x.id INTO v_xr FROM public.exemplar_drafts x WHERE x.import_staging_row_id = v_rrow;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    PERFORM public.fn_batch_review_verdict((v_res->>'review_id')::bigint, 'approved', NULL);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_er := public.publish_exemplar_draft(v_xr);
    EXECUTE 'RESET ROLE';
    v_n := (SELECT count(*) FROM public.book_external_ids e WHERE e.book_id = v_rb AND e.library_id = v_lib AND e.value = 'L1-RAT');
    -- « Réattribuer à une autre bibliothèque » (ExemplarDraftForm.handleReassignLibrary),
    -- par l'administration du réseau : cible B, détention et tombo vidés, sorti du lot.
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    UPDATE public.exemplar_drafts
       SET target_library_id = v_libB, target_holding_id = NULL, tombo = NULL, updated_by = v_admin, batch_id = NULL
     WHERE id = v_xr;
    PERFORM public.publish_exemplar_draft(v_xr);
    EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    IF v_n = 1
       AND (SELECT e.library_id FROM public.exemplares e WHERE e.id = v_er) = v_libB
       AND (SELECT count(*) FROM public.book_external_ids e WHERE e.book_id = v_rb AND e.library_id = v_lib
              AND e.value = 'L1-RAT' AND e.scheme = 'import:' || v_s1) = 1
       AND NOT EXISTS (SELECT 1 FROM public.book_external_ids e WHERE e.library_id = v_libB AND e.value = 'L1-RAT')
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : avant='||coalesce(v_n::text,'NULL')||' exemplaire a '
         ||coalesce((SELECT CASE e.library_id WHEN v_lib THEN 'BLMF' WHEN v_libB THEN 'B' ELSE e.library_id::text END FROM public.exemplares e WHERE e.id = v_er),'NULL')
         ||' ; identifiants : '||coalesce((SELECT string_agg(CASE e.library_id WHEN v_lib THEN 'BLMF' WHEN v_libB THEN 'B' ELSE e.library_id::text END
                                                  ||'/'||e.scheme||'/'||e.value, ', ') FROM public.book_external_ids e WHERE e.value = 'L1-RAT'), 'aucun')); END IF;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_hint,'')||' '||SQLERRM); END;

  -- ── Décor de T11-T15 : une notice importée et trois exemplaires du fichier ──
  -- X2 et X3 sont à la corbeille quand la révision est demandée ; X2 en sort après la
  -- demande (avant la publication de sa notice), X3 après le second tour.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
  INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
  VALUES (v_s1, v_lib, 'essai/l1-rattaches.marc', 'l1-rattaches.marc', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_rd;
  INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, match_status, editorial_decision, normalized_payload)
  VALUES (v_rd, 1, 'L1-D', 'L1 Notice importee et ses trois exemplaires', 'new_record', 'accept_new',
          '{"items": [{"source_item_code": "L1-D-1", "call_number": "D1"}, {"source_item_code": "L1-D-2", "call_number": "D2"},
                      {"source_item_code": "L1-D-3", "call_number": "D3"}]}'::jsonb);
  v_lotd := (public.fn_import_promote(v_rd, ARRAY['new_record'], ARRAY['accept_new'])->>'batch_id')::bigint;
  SELECT m.draft_id INTO v_nd FROM ingest.partner_catalog_row_to_draft m JOIN ingest.partner_catalog_staging_rows s ON s.id = m.staging_row_id WHERE s.run_id = v_rd;
  SELECT x.id INTO v_x1 FROM public.exemplar_drafts x WHERE x.book_draft_id = v_nd AND x.source_item_code = 'L1-D-1';
  SELECT x.id INTO v_x2 FROM public.exemplar_drafts x WHERE x.book_draft_id = v_nd AND x.source_item_code = 'L1-D-2';
  SELECT x.id INTO v_x3 FROM public.exemplar_drafts x WHERE x.book_draft_id = v_nd AND x.source_item_code = 'L1-D-3';
  UPDATE public.book_drafts SET bib_ref = 'L1-REF-' || id, tipo_material = 'livro' WHERE id = v_nd;
  UPDATE public.exemplar_drafts SET status = 'cancelled' WHERE id IN (v_x2, v_x3);
  v_res := public.fn_batch_review_request(v_lotd, 'L1 : notice et exemplaires');
  v_rev := (v_res->>'review_id')::bigint;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
  PERFORM public.fn_batch_review_verdict(v_rev, 'approved', NULL);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
  -- X2 sort de la corbeille APRÈS la demande (le journal, ou l'écran « Restaurer »).
  UPDATE public.exemplar_drafts SET status = 'draft' WHERE id = v_x2;

  -- ── T11 ─────────────────────────────────────────────────────────────
  v_t := 'T11 (IMP-28 d) publish_book_draft publie la notice et l''exemplaire couvert, laisse en brouillon le rattache restaure apres la demande';
  BEGIN
    IF v_x1 IS NULL OR v_x2 IS NULL OR v_x3 IS NULL THEN RAISE EXCEPTION 'decor : la promotion n''a pas cree les trois exemplaires'; END IF;
    v_bookd := public.publish_book_draft(v_nd);
    IF v_bookd IS NOT NULL
       AND (SELECT status FROM public.book_drafts WHERE id = v_nd) = 'published'
       AND (SELECT status FROM public.exemplar_drafts WHERE id = v_x1) = 'published'
       AND (SELECT status FROM public.exemplar_drafts WHERE id = v_x2) = 'draft'
       AND (SELECT r.exemplar_draft_ids = ARRAY[v_x1] FROM public.catalog_batch_reviews r WHERE r.id = v_rev)
       AND (SELECT count(*) FROM public.exemplares e WHERE e.source_item_code = 'L1-D-1' AND e.library_id = v_lib) = 1
       AND NOT EXISTS (SELECT 1 FROM public.exemplares e WHERE e.source_item_code = 'L1-D-2')
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '
         ||coalesce((SELECT string_agg(x.source_item_code||'='||x.status, ' ' ORDER BY x.id) FROM public.exemplar_drafts x WHERE x.book_draft_id = v_nd), 'aucun')); END IF;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_hint,'')||' '||SQLERRM); END;

  -- ── T12 ─────────────────────────────────────────────────────────────
  v_t := 'T12 (IMP-28 d) publish_exemplar_draft refuse le rattache restaure apres la demande (added_after_review)';
  BEGIN
    v_hint := NULL;
    BEGIN
      PERFORM public.publish_exemplar_draft(v_x2);
      v_hint := 'publie';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    END;
    IF v_hint = 'error.publish.added_after_review'
       AND NOT EXISTS (SELECT 1 FROM public.exemplares e WHERE e.source_item_code = 'L1-D-2')
       AND (SELECT status FROM public.exemplar_drafts WHERE id = v_x2) = 'draft'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_hint,'NULL')); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T13 ─────────────────────────────────────────────────────────────
  v_t := 'T13 (IMP-28 d) le rattache compte dans les ajouts : la coordination redemande un tour, qui le soumet';
  BEGIN
    v_n := public.fn_batch_ajouts_apres_revision(v_lotd);
    EXECUTE 'SET LOCAL ROLE authenticated';
    SELECT l.after_review INTO v_m FROM public.fn_batch_reviews_list() l WHERE l.batch_id = v_lotd;
    v_res := public.fn_batch_review_request(v_lotd, 'L1 : un exemplaire sorti de la corbeille');
    EXECUTE 'RESET ROLE';
    v_rev := (v_res->>'review_id')::bigint;
    IF v_n = 1 AND v_m = 1
       AND (SELECT r.round = 2 AND r.status = 'requested' AND r.requested_by = v_coord AND v_x2 = ANY (r.exemplar_draft_ids)
              FROM public.catalog_batch_reviews r WHERE r.id = v_rev)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : ajouts='||coalesce(v_n::text,'NULL')||' after_review='||coalesce(v_m::text,'NULL')
         ||' demande='||coalesce(v_res::text,'NULL')); END IF;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    EXECUTE 'RESET ROLE';
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_hint,'')||' '||SQLERRM); END;

  -- ── T14 ─────────────────────────────────────────────────────────────
  v_t := 'T14 (IMP-28 d) le tour 2 approuve, le rattache se publie sur la fiche de sa notice';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    PERFORM public.fn_batch_review_verdict(v_rev, 'approved', NULL);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    PERFORM public.publish_exemplar_draft(v_x2);
    IF (SELECT status FROM public.exemplar_drafts WHERE id = v_x2) = 'published'
       AND (SELECT count(*) FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id
             WHERE e.source_item_code = 'L1-D-2' AND e.library_id = v_lib AND h.book_id = v_bookd
               AND e.bib_ref = 'L1-REF-' || v_nd) = 1
       AND public.fn_batch_ajouts_apres_revision(v_lotd) = 0
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : exemplaire absent ou hors de la fiche'); END IF;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_hint,'')||' '||SQLERRM); END;

  -- ── T15 ─────────────────────────────────────────────────────────────
  v_t := 'T15 (IMP-28 d) un rattache restaure, sa notice publiee sortie de son lot : imported_needs_batch';
  BEGIN
    UPDATE public.exemplar_drafts SET status = 'draft' WHERE id = v_x3;
    UPDATE public.book_drafts SET batch_id = NULL WHERE id = v_nd;   -- « Sans lot » ; ses exemplaires suivent
    IF (SELECT x.batch_id IS NOT NULL OR x.status <> 'draft' FROM public.exemplar_drafts x WHERE x.id = v_x3) THEN
      RAISE EXCEPTION 'decor : X3 n''a pas suivi sa notice hors du lot';
    END IF;
    v_hint := NULL;
    BEGIN
      PERFORM public.publish_exemplar_draft(v_x3);
      v_hint := 'publie';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    END;
    IF v_hint = 'error.publish.imported_needs_batch'
       AND NOT EXISTS (SELECT 1 FROM public.exemplares e WHERE e.source_item_code = 'L1-D-3')
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_hint,'NULL')); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T16 ─────────────────────────────────────────────────────────────
  v_t := 'T16 (IMP-28 d) « Publier le lot » et un rattache dont la notice est deja publiee : refuse tant qu''aucun tour ne le couvre, publie apres le nouveau tour';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_s1, v_lib, 'essai/l1-lot.marc', 'l1-lot.marc', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_re;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, match_status, editorial_decision, normalized_payload)
    VALUES (v_re, 1, 'L1-E', 'L1 Notice publiee seule, puis le lot', 'new_record', 'accept_new',
            '{"items": [{"source_item_code": "L1-E-1", "call_number": "E1"}, {"source_item_code": "L1-E-2", "call_number": "E2"}]}'::jsonb);
    v_lote := (public.fn_import_promote(v_re, ARRAY['new_record'], ARRAY['accept_new'])->>'batch_id')::bigint;
    SELECT m.draft_id INTO v_ne FROM ingest.partner_catalog_row_to_draft m JOIN ingest.partner_catalog_staging_rows s ON s.id = m.staging_row_id WHERE s.run_id = v_re;
    SELECT x.id INTO v_e2 FROM public.exemplar_drafts x WHERE x.book_draft_id = v_ne AND x.source_item_code = 'L1-E-2';
    UPDATE public.book_drafts SET bib_ref = 'L1-REF-' || id, tipo_material = 'livro' WHERE id = v_ne;
    UPDATE public.exemplar_drafts SET status = 'cancelled' WHERE id = v_e2;
    v_res := public.fn_batch_review_request(v_lote, 'L1 : le lot E');
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    PERFORM public.fn_batch_review_verdict((v_res->>'review_id')::bigint, 'approved', NULL);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    UPDATE public.exemplar_drafts SET status = 'draft' WHERE id = v_e2;   -- sorti de la corbeille après la demande
    v_booke := public.publish_book_draft(v_ne);                          -- la notice et L1-E-1 ; L1-E-2 attend
    v_hint := NULL;
    BEGIN
      PERFORM public.publish_catalog_batch(v_lote);
      v_hint := 'lot publie';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    END;
    v_txt := (SELECT b.status FROM public.catalog_batches b WHERE b.id = v_lote);
    v_res := public.fn_batch_review_request(v_lote, 'L1 : L1-E-2 sorti de la corbeille');
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    PERFORM public.fn_batch_review_verdict((v_res->>'review_id')::bigint, 'approved', NULL);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_res2 := public.publish_catalog_batch(v_lote);
    IF v_hint = 'error.publish.added_after_review' AND v_txt = 'open'
       AND (v_res2->>'exemplars_published')::int = 1
       AND (SELECT status FROM public.exemplar_drafts WHERE id = v_e2) = 'published'
       AND (SELECT b.status FROM public.catalog_batches b WHERE b.id = v_lote) = 'published'
       AND (SELECT count(*) FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id
             WHERE e.source_item_code IN ('L1-E-1', 'L1-E-2') AND e.library_id = v_lib AND h.book_id = v_booke) = 2
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : premier essai='||coalesce(v_hint,'NULL')||' lot='||coalesce(v_txt,'NULL')
         ||' second='||coalesce(v_res2::text,'NULL')||' L1-E-2='||coalesce((SELECT status FROM public.exemplar_drafts WHERE id = v_e2),'NULL')); END IF;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_hint,'')||' '||SQLERRM); END;

  -- ── T17 ─────────────────────────────────────────────────────────────
  v_t := 'T17 structure et droits : index (library_id, value), liste ouverte a l''ecran, rapprochement ferme';
  BEGIN
    IF EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname = 'public' AND tablename = 'book_external_ids'
                  AND indexdef ~ '\(library_id, value\)')
       AND has_function_privilege('authenticated', 'public.fn_import_list_run_rows(bigint)', 'EXECUTE')
       AND has_function_privilege('service_role', 'public.fn_import_list_run_rows(bigint)', 'EXECUTE')
       AND NOT has_function_privilege('anon', 'public.fn_import_list_run_rows(bigint)', 'EXECUTE')
       AND NOT has_function_privilege('authenticated', 'ingest.fn_match_partner_catalog_row(bigint)', 'EXECUTE')
       AND NOT has_function_privilege('anon', 'ingest.fn_match_partner_catalog_row(bigint)', 'EXECUTE')
       AND (SELECT format_type(t, NULL) FROM pg_proc p, unnest(p.proallargtypes) WITH ORDINALITY u(t, n)
             WHERE p.oid = 'public.fn_import_list_run_rows(bigint)'::regprocedure
             ORDER BY n DESC LIMIT 1) = 'boolean'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : structure ou droits'); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T18 ─────────────────────────────────────────────────────────────
  v_t := 'T18 (IMP-28 c) lot du PMB de BLMF reattribue a B avant publication : l''identifiant reste a BLMF ; le PMB de B, cle homonyme : pas reconnue';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_s1, v_lib, 'essai/l1-lot-reattribue.marc', 'l1-lot-reattribue.marc', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_rh;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, match_status, editorial_decision, normalized_payload)
    VALUES (v_rh, 1, 'L1-123', 'L1 Notice du PMB de BLMF, lot reattribue', 'new_record', 'accept_new', '{"items": []}'::jsonb),
           (v_rh, 2, 'L1-124', 'L1 Son doublon dans le meme fichier', 'new_record', 'accept_new', '{"items": []}'::jsonb);
    v_loth := (public.fn_import_promote(v_rh, ARRAY['new_record'], ARRAY['accept_new'])->>'batch_id')::bigint;
    SELECT m.draft_id INTO v_dh FROM ingest.partner_catalog_row_to_draft m JOIN ingest.partner_catalog_staging_rows s ON s.id = m.staging_row_id WHERE s.run_id = v_rh AND s.row_no = 1;
    SELECT m.draft_id INTO v_dh2 FROM ingest.partner_catalog_row_to_draft m JOIN ingest.partner_catalog_staging_rows s ON s.id = m.staging_row_id WHERE s.run_id = v_rh AND s.row_no = 2;
    UPDATE public.book_drafts SET bib_ref = 'L1-REF-' || id, tipo_material = 'livro' WHERE id IN (v_dh, v_dh2);
    -- La coordination fond le doublon dans la notice (fusion de brouillons) : à la
    -- publication du survivant, l'identifiant de l'absorbé est posé aussi.
    PERFORM api.merge_book_drafts(v_dh, v_dh2, '{}'::jsonb);
    -- L'administration du réseau réattribue le lot à B (le run reste celui de BLMF),
    -- demande la révision, l'approuve, publie.
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    PERFORM public.fn_batch_reassign_library(v_loth, v_libB);
    v_res := public.fn_batch_review_request(v_loth, 'L1 : lot reattribue a B');
    PERFORM public.fn_batch_review_verdict((v_res->>'review_id')::bigint, 'approved', NULL);
    v_bookh := public.publish_book_draft(v_dh);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    -- B importe son PMB : le numéro L1-123 y est une autre œuvre.
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_sB, v_libB, 'essai/l1-pmb-de-b.marc', 'l1-pmb-de-b.marc', 'marc_iso2709', 'parsed') RETURNING id INTO v_rhb;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, match_status, editorial_decision, normalized_payload)
    VALUES (v_rhb, 1, 'L1-123', 'L1 Une autre oeuvre au meme numero, chez B', 'unreviewed', 'pending', '{"items": []}'::jsonb);
    PERFORM ingest.fn_match_partner_catalog_run(v_rhb);
    -- Et BLMF, qui réimporte son PMB : reconnue (plus détenue par BLMF : la notice est à B).
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_s2, v_lib, 'essai/l1-pmb-de-blmf-encore.marc', 'l1-pmb-de-blmf-encore.marc', 'marc_iso2709', 'parsed') RETURNING id INTO v_rhb2;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, match_status, editorial_decision, normalized_payload)
    VALUES (v_rhb2, 1, 'L1-123', 'L1 Notice du PMB de BLMF, reimportee', 'unreviewed', 'pending', '{"items": []}'::jsonb);
    PERFORM ingest.fn_match_partner_catalog_run(v_rhb2);
    IF v_bookh IS NOT NULL
       AND EXISTS (SELECT 1 FROM public.book_holdings h WHERE h.book_id = v_bookh AND h.library_id = v_libB)
       AND (SELECT string_agg(e.value, ',' ORDER BY e.value) FROM public.book_external_ids e WHERE e.book_id = v_bookh AND e.library_id = v_lib
              AND e.scheme = 'import:' || v_s1) = 'L1-123,L1-124'
       AND NOT EXISTS (SELECT 1 FROM public.book_external_ids e WHERE e.library_id = v_libB AND e.value IN ('L1-123', 'L1-124'))
       AND (SELECT sr.match_status = 'new_record' AND sr.proposed_book_id IS NULL
              FROM ingest.partner_catalog_staging_rows sr WHERE sr.run_id = v_rhb)
       AND (SELECT sr.match_status = 'known_record' AND sr.proposed_book_id = v_bookh
              FROM ingest.partner_catalog_staging_rows sr WHERE sr.run_id = v_rhb2)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : identifiants='
         ||coalesce((SELECT string_agg(CASE e.library_id WHEN v_lib THEN 'BLMF' WHEN v_libB THEN 'B' ELSE e.library_id::text END||'/'||e.value, ', ')
                       FROM public.book_external_ids e WHERE e.value IN ('L1-123', 'L1-124')), 'aucun')
         ||' ; PMB de B='||coalesce((SELECT sr.match_status||'/'||coalesce(sr.proposed_book_id::text,'-') FROM ingest.partner_catalog_staging_rows sr WHERE sr.run_id = v_rhb),'NULL')
         ||' ; BLMF='||coalesce((SELECT sr.match_status||'/'||coalesce(sr.proposed_book_id::text,'-') FROM ingest.partner_catalog_staging_rows sr WHERE sr.run_id = v_rhb2),'NULL')); END IF;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_hint,'')||' '||SQLERRM); END;

  -- ── T19 ─────────────────────────────────────────────────────────────
  v_t := 'T19 fusion de notices (fn_fusion_notices) : la valeur ambigue avant la fusion designe ensuite UNE notice, la gardee';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    INSERT INTO public.books (titulo, bib_ref, tipo_material, owner_library_id) VALUES ('L1 Doublon a fondre', 'L1-FA', 'livro', v_lib) RETURNING id INTO v_fa;
    INSERT INTO public.books (titulo, bib_ref, tipo_material, owner_library_id) VALUES ('L1 Notice gardee', 'L1-FB', 'livro', v_lib) RETURNING id INTO v_fb;
    INSERT INTO public.book_holdings (book_id, library_id) VALUES (v_fa, v_lib), (v_fb, v_lib);
    PERFORM ingest.fn_record_book_external_id(v_fa, v_lib, v_s1, 'L1-F');   -- le premier export : le doublon
    PERFORM ingest.fn_record_book_external_id(v_fb, v_lib, v_s2, 'L1-F');   -- le nouvel export : la gardée
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_s2, v_lib, 'essai/l1-fusion.marc', 'l1-fusion.marc', 'marc_iso2709', 'parsed') RETURNING id INTO v_rf;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, match_status, editorial_decision, normalized_payload)
    VALUES (v_rf, 1, 'L1-F', 'L1 Fondue', 'unreviewed', 'pending', '{"items": []}'::jsonb);
    PERFORM ingest.fn_match_partner_catalog_run(v_rf);
    v_txt := (SELECT sr.match_status FROM ingest.partner_catalog_staging_rows sr WHERE sr.run_id = v_rf);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    PERFORM public.fn_fusion_notices(v_fb, v_fa);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    PERFORM ingest.fn_match_partner_catalog_run(v_rf);
    IF v_txt <> 'known_record'
       AND NOT EXISTS (SELECT 1 FROM public.books WHERE id = v_fa)
       AND (SELECT count(*) FROM public.book_external_ids e WHERE e.value = 'L1-F' AND e.library_id = v_lib AND e.book_id = v_fb) = 2
       AND (SELECT sr.match_status = 'known_record' AND sr.proposed_book_id = v_fb
              FROM ingest.partner_catalog_staging_rows sr WHERE sr.run_id = v_rf)
       AND NOT EXISTS (SELECT 1 FROM ingest.partner_catalog_staging_rows sr, jsonb_array_elements(sr.warnings) w
                        WHERE sr.run_id = v_rf AND w->>'kind' = 'known_record_ambiguous')
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : avant='||coalesce(v_txt,'NULL')||' apres='
         ||coalesce((SELECT sr.match_status||'/'||coalesce(sr.proposed_book_id::text,'-') FROM ingest.partner_catalog_staging_rows sr WHERE sr.run_id = v_rf),'NULL')
         ||' (gardee='||v_fb||')'); END IF;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_hint,'')||' '||SQLERRM); END;

  -- ── T20 ─────────────────────────────────────────────────────────────
  v_t := 'T20 ligne reconnue dont la notice est supprimee depuis : l''ecran la lit, « Rapprocher » l''ignore sans erreur, « Rejeter » passe';
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    INSERT INTO public.books (titulo, bib_ref, tipo_material, owner_library_id) VALUES ('L1 Notice supprimee ensuite', 'L1-DEL', 'livro', v_lib) RETURNING id INTO v_fd;
    PERFORM ingest.fn_record_book_external_id(v_fd, v_lib, v_s1, 'L1-DEL');
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_s2, v_lib, 'essai/l1-supprimee.marc', 'l1-supprimee.marc', 'marc_iso2709', 'parsed') RETURNING id INTO v_rdel;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, match_status, editorial_decision, normalized_payload)
    VALUES (v_rdel, 1, 'L1-DEL', 'L1 Reconnue, notice supprimee', 'unreviewed', 'pending',
            '{"items": [{"source_item_code": "L1-DEL-1"}]}'::jsonb)
    RETURNING id INTO v_rowdel;
    PERFORM ingest.fn_match_partner_catalog_run(v_rdel);
    v_txt := (SELECT sr.match_status FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = v_rowdel);
    DELETE FROM public.books WHERE id = v_fd;   -- la clé étrangère de la ligne passe à NULL
    EXECUTE 'SET LOCAL ROLE authenticated';
    SELECT l.match_status || '/' || coalesce(l.proposed_book_id::text, 'null') || '/' || coalesce(l.proposed_book_held::text, 'null')
      INTO v_txt2 FROM public.fn_import_list_run_rows(v_rdel) l WHERE l.id = v_rowdel;
    v_res := public.fn_import_reconcile_duplicates(v_rdel, ARRAY[v_rowdel]);
    v_res2 := public.fn_import_set_editorial(v_rdel, ARRAY[v_rowdel], 'reject', 'L1 : la notice reconnue n''existe plus');
    EXECUTE 'RESET ROLE';
    IF v_txt = 'known_record' AND v_txt2 = 'known_record/null/null'
       AND (v_res->>'skipped_rows')::int = 1 AND coalesce((v_res->>'created_items')::int, 0) = 0
       AND NOT EXISTS (SELECT 1 FROM public.exemplar_drafts x WHERE x.import_staging_row_id = v_rowdel)
       AND (v_res2->>'updated_rows')::int = 1
       AND (SELECT editorial_decision FROM ingest.partner_catalog_staging_rows WHERE id = v_rowdel) = 'reject'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : avant='||coalesce(v_txt,'NULL')||' ecran='||coalesce(v_txt2,'NULL')
         ||' rapprocher='||coalesce(v_res::text,'NULL')||' rejeter='||coalesce(v_res2::text,'NULL')); END IF;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    EXECUTE 'RESET ROLE';
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_hint,'')||' '||SQLERRM); END;

  IF v_failed = 0 THEN
    RAISE EXCEPTION 'H21-LOT1-RECONNAITRE OK : %/% tests passés', v_passed, (v_passed+v_failed);
  ELSE
    RAISE EXCEPTION 'H21-LOT1-RECONNAITRE ECHEC : %/% OK, % échec(s) | %',
      v_passed, (v_passed+v_failed), v_failed, array_to_string(v_failures, ' || ');
  END IF;
END $$;
